import type { NextConfig } from "next";
import fs from "node:fs";
import path from "node:path";

// amplify_outputs.json is generated by Amplify (sandbox locally, or the
// pipeline-deploy step on Amplify Hosting). Reading it here and passing it on
// as an environment value means the site still builds and runs on sample
// content when no backend has been deployed yet.
function readAmplifyOutputs(): string {
  try {
    return fs.readFileSync(path.join(process.cwd(), "amplify_outputs.json"), "utf8");
  } catch {
    return "";
  }
}

const nextConfig: NextConfig = {
  env: {
    AMPLIFY_OUTPUTS: readAmplifyOutputs(),
  },
};

export default nextConfig;
